<?php
require '../app/core/bootstrap.php';auth();require '../app/core/layout.php';
$rows=$pdo->query('SELECT pw.*,p.nombre producto,pr.nombre proveedor FROM precios_web pw LEFT JOIN productos p ON p.id=pw.producto_id LEFT JOIN proveedores pr ON pr.id=pw.proveedor_id ORDER BY pw.capturado_at DESC LIMIT 200')->fetchAll();head('Precios');
